import{_ as a,a as r,c as p,ac as t}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"CMake 构建：目标、依赖与可搬移包","description":"从构建阶段和目标图接续到 PUBLIC、安装导出与消费。","frontmatter":{"title":"CMake 构建：目标、依赖与可搬移包","description":"从构建阶段和目标图接续到 PUBLIC、安装导出与消费。","showdocs":{"topics":[{"id":"cpp","title":"C++","link":"/topics/cpp/"}],"kind":"知识专题","scope":"general","audience":"general","group":"语言与开发","seriesTitle":"C++ 大型构建：目标图与可搬移包","summary":"从构建阶段和目标图接续到 PUBLIC、安装导出与消费。","status":"active","related":[{"title":"C++ 构建排错：头文件、包发现、配置与规模","link":"/programming/cpp/plus/troubleshooting/build-diagnostics","kind":"排错","scope":"general","audience":"general"},{"title":"C++ 完整 SPSC 实践：固定载荷、回绕与双线程测试","link":"/programming/cpp/plus/practice/spsc-application","kind":"开发实践","scope":"general","audience":"general"},{"title":"C++ 完整 SPSC 实践：固定载荷、回绕与双线程测试 · SPSC测试怎样覆盖空满回绕和有序压力至一手资料与验证边界","link":"/programming/cpp/plus/practice/spsc-application-part-03","kind":"开发实践","scope":"general","audience":"general"},{"title":"C++ 完整 SPSC 实践：固定载荷、回绕与双线程测试 · SPSC完整工程怎样传输和校验消息","link":"/programming/cpp/plus/practice/spsc-application-part-01","kind":"开发实践","scope":"general","audience":"general"},{"title":"C++ 完整 SPSC 实践：固定载荷、回绕与双线程测试 · SPSC完整项目的头文件入口测试怎样共享源码至SPSC示例怎样构建且区分预期与执行","link":"/programming/cpp/plus/practice/spsc-application-part-02","kind":"开发实践","scope":"general","audience":"general"}],"prev":{"text":"C++ 首批课程：值语义、RAII与库存汇总项目","link":"/programming/cpp/base/intermediate/foundations"},"next":{"text":"C++ 完整构建实践：库、CLI、测试与安装后消费","link":"/programming/cpp/plus/practice/build-application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"C++ 首批课程：值语义、RAII与库存汇总项目","link":"/programming/cpp/base/intermediate/foundations"},"next":{"text":"C++ 完整构建实践：库、CLI、测试与安装后消费","link":"/programming/cpp/plus/practice/build-application"}},"headers":[],"relativePath":"programming/cpp/build-system.md","filePath":"programming/cpp/build-system.md"}'),i={name:"programming/cpp/build-system.md"};function n(o,e,s,c,l,d){return r(),p("div",null,[...e[0]||(e[0]=[t('<h1 id="cmake-构建-目标、依赖与可搬移包" tabindex="-1">CMake 构建：目标、依赖与可搬移包 <a class="header-anchor" href="#cmake-构建-目标、依赖与可搬移包" aria-label="Permalink to &quot;CMake 构建：目标、依赖与可搬移包&quot;">​</a></h1><h2 id="part-1" tabindex="-1">目标图、阶段与缓存 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;目标图、阶段与缓存 {#part-1}&quot;">​</a></h2><p>先跟随<a href="/programming/cpp/base/intermediate/foundations#library">库存汇总的分离编译</a>理解头文件和翻译单元。现在有库、测试和 CLI 三个目标：修改实现只需重建受影响的目标，导出的公共接口还能被一个新的消费者使用。<a href="/programming/cpp/plus/practice/build-application#source">完整目标图与预设</a></p><p>专题入口：<a href="#part-1">C++ 大型构建模型：目标图、阶段与缓存</a> · <a href="#part-2">C++ 构建依赖：PUBLIC、私有头与可搬移包</a> · <a href="/programming/cpp/plus/practice/build-application">C++ 完整构建实践：库、CLI、测试与安装后消费</a> · <a href="/programming/cpp/plus/troubleshooting/build-diagnostics">C++ 构建排错：头文件、包发现、配置与规模</a></p><h3 id="part-1-scope" tabindex="-1">C++大型构建教学采用什么版本 <a class="header-anchor" href="#part-1-scope" aria-label="Permalink to &quot;C++大型构建教学采用什么版本 {#part-1-scope}&quot;">​</a></h3><p>工程要求 CMake 3.28 以上和 C++20，其 Presets 使用 schema 8 和 Ninja 单配置生成器。使用其他生成器时，另选空构建目录并显式指定构建类型，同一个目标图可以由不同后端生成。</p><p>Windows 原生假设已初始化的 MSVC 开发者 PowerShell；Linux 假设 GCC/Clang 与配套标准库；macOS 假设 AppleClang 与 SDK。每次记录编译器、架构、运行库与 CMake 版本才能讨论二进制兼容；同是 C++20 不保证不同 ABI 的静态库可以互链。先读<a href="/programming/cpp/base/intermediate/foundations#raii">RAII基础</a>，再按本系列进入目标依赖与完整工程。</p><h3 id="part-1-phases" tabindex="-1">CMake配置生成构建安装各做什么 <a class="header-anchor" href="#part-1-phases" aria-label="Permalink to &quot;CMake配置生成构建安装各做什么 {#part-1-phases}&quot;">​</a></h3><p>配置执行 CMakeLists 并建立目标与属性；生成把目标图翻译为 Ninja 或 IDE 的构建规则；构建由后端驱动预处理、编译和链接；安装把已构建产物与声明的包元数据复制到前缀。配置/生成常由一次 cmake 调用完成，但它们与编译仍是不同阶段。</p><p><code>find_package</code> 没找到包通常在配置阶段报错，找不到头发生在编译阶段，缺少符号发生在链接阶段。先读第一条诊断，再对应检查前缀、目标头目录或链接依赖。安装时丢失 Config 文件能让源码树内构建成功，却使外部消费者无法配置。</p><p>构建不是仅把所有 cpp 拼成一个命令。库先编成自己的对象/归档，CLI 和测试分别链接库；改变库的实现会重编相关对象并重新链接依赖产物，改变公共头可能触及所有包含它的翻译单元。</p><h3 id="part-1-targets" tabindex="-1">大型CMake工程为什么围绕target组织 <a class="header-anchor" href="#part-1-targets" aria-label="Permalink to &quot;大型CMake工程为什么围绕target组织 {#part-1-targets}&quot;">​</a></h3><p>target 是依赖图的节点，连接产物与用法要求；一个库拥有自己的源、头目录、编译特性和依赖。目录只是存放文件，不是传播范围的可靠边界。全局 include_directories 或 CMAKE_CXX_FLAGS 容易让本不相关的目标意外可编译，掩盖缺失依赖。</p><p>本例用 p2_report 表示可链接静态库，p2_options 是无产物的 INTERFACE 目标，用于共享 C++20 约束。P2::report/P2::options 是构建树 ALIAS；ALIAS 本身不能直接安装，实际目标通过 EXPORT_NAME 导出同名的 imported target。CLI 与测试只链接 P2::report，不手工重复它的 include 目录。</p><p>多模块工程可让每个子目录定义少量清晰目标，以 target_link_libraries 表达图，避免所有模块链接一个汇总“万能库”。不要为演示规模人为拆出十几个库；边界应由公共 API、复用关系与独立维护需求决定。</p><h3 id="part-1-cache" tabindex="-1">CMakePresets怎样隔离Debug和Release缓存 <a class="header-anchor" href="#part-1-cache" aria-label="Permalink to &quot;CMakePresets怎样隔离Debug和Release缓存 {#part-1-cache}&quot;">​</a></h3><p>本例 binaryDir 为 out/${presetName}，debug/release 分别设置 CMAKE_BUILD_TYPE，从而隔离 CMakeCache.txt、对象与产物。隐藏 base 只共享 Ninja 和 BUILD_TESTING，不能直接作为可执行 preset；同名 build/test preset 显式指向对应 configurePreset。</p><p>Presets 固定可共享的项目选择，不应提交个人编译器绝对路径。用户机器设置放 CMakeUserPresets.json，并加入忽略规则。换生成器、架构或工具链时使用新构建目录；仅修改环境变量未必改变缓存中的编译器。缓存不是依赖锁文件，也不等于可复现的完整工具链环境。</p><p>单配置生成器在配置时选构建类型；Visual Studio 或 Ninja Multi-Config 在构建时选 --config。不能把两种命令拼在一起并假定同一输出目录。本例只提供单配置 preset；若要添加多配置方案，需一起修改 build/test configuration、安装 --config 与输出路径。</p><h3 id="part-1-exercise" tabindex="-1">练习与自检 <a class="header-anchor" href="#part-1-exercise" aria-label="Permalink to &quot;练习与自检 {#part-1-exercise}&quot;">​</a></h3><p>解释为何在同一个 out/debug 中从 Ninja 切到 Visual Studio 会造成缓存冲突；为第三种工具链提出目录命名方式。</p><details><summary>参考答案与判断依据</summary><p>生成器、编译器与 ABI 都参与构建树身份。保留已有目录，另用 out/msvc-debug 或 out/clang-debug 配置；目录名是约定，真正证据仍包括 preset 与缓存中的实际工具链。不通过删改旧缓存掩盖未知环境。</p></details><h3 id="part-1-sources" tabindex="-1">一手资料与验证边界 <a class="header-anchor" href="#part-1-sources" aria-label="Permalink to &quot;一手资料与验证边界 {#part-1-sources}&quot;">​</a></h3><p>2026-10-17核对 <a href="https://cmake.org/cmake/help/v3.28/manual/cmake-presets.7.html" target="_blank" rel="noopener noreferrer">CMake 3.28 Presets</a>、<a href="https://cmake.org/cmake/help/v3.28/guide/importing-exporting/index.html" target="_blank" rel="noopener noreferrer">导入导出指南</a>、<a href="https://cmake.org/cmake/help/v3.28/module/CMakePackageConfigHelpers.html" target="_blank" rel="noopener noreferrer">PackageConfigHelpers</a>。复现步骤与独立消费者的输出见<a href="/programming/cpp/plus/practice/build-application#acceptance">安装后消费</a>。</p><h2 id="part-2" tabindex="-1">PUBLIC、私有头与可搬移包 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;PUBLIC、私有头与可搬移包 {#part-2}&quot;">​</a></h2><p>构建树中的别名 <code>P2::report</code> 与安装后导入的目标名称相同。前者引用当前工程的定义，后者从安装包加载接口和归档的位置。跟随<a href="/programming/cpp/plus/practice/build-application#source">安装配置和独立 consumer</a>逐一确认两者提供的用法要求。</p><h3 id="part-2-scope" tabindex="-1">CMake的PUBLIC PRIVATE INTERFACE怎样选择 <a class="header-anchor" href="#part-2-scope" aria-label="Permalink to &quot;CMake的PUBLIC PRIVATE INTERFACE怎样选择 {#part-2-scope}&quot;">​</a></h3><p>PRIVATE 只用于当前目标的编译需求；INTERFACE 只给消费者；PUBLIC 同时用于当前目标和消费者。判断依据是公共 API 是否要求消费者看到某项约束，而不是想“保险一点”就全部 PUBLIC。</p><p>p2_report 的公共头用 C++20 接口，因而 PUBLIC 链接 P2::options；options 的 cxx_std_20 是 INTERFACE 要求。src 和 generated 头目录 PRIVATE，不该泄漏进 CLI。CLI 自己无须向任何目标传播库依赖，所以 PRIVATE 链接 report。警告开关也是库自己的 PRIVATE 构建政策，不强加给第三方消费者。</p><p>静态库的 PRIVATE 链接依赖还有链接阶段传播细节：归档并没有把依赖库代码自动复制进去，CMake 可能为最终链接保留仅链接依赖。不能把 PRIVATE 解释为最终链接永远不需要它；外部依赖还要在安装包 Config 中用 find_dependency 恢复相应目标。本例没有第三方链接依赖，避免把这个边界藏起来。</p><h3 id="part-2-headers" tabindex="-1">公共头与生成头为什么分开目录 <a class="header-anchor" href="#part-2-headers" aria-label="Permalink to &quot;公共头与生成头为什么分开目录 {#part-2-headers}&quot;">​</a></h3><p>include/p2/report.hpp 是 API，src/detail.hpp 是实现，version.hpp 由 configure_file 生成在构建树。BUILD_INTERFACE 为源码构建提供公共头位置，INSTALL_INTERFACE 只记录相对安装头目录，让 imported target 在新前缀下重新定位。</p><p>version() 返回指向静态字符串字面量的 string_view，因此返回后仍有效；configure_file 只替换项目版本，不在公共 API 中暴露生成头。消费者不应知道 generated 目录，更不应依赖私有 detail.hpp。若公共头自己 include 了生成头，则该生成头也是公共安装契约，需要显式安装并设置可搬移的 include 关系。</p><p>不要在 INSTALL_INTERFACE 填当前机器的绝对源码路径或另一个依赖的 include 路径；依赖应通过它自己的 imported target 提供。实践项目用 GNUInstallDirs 处理平台目录习惯，仍需在实际平台验证目录布局，而不是承诺任意定制安装路径都可搬移。</p><h3 id="part-2-export" tabindex="-1">CMake怎样安装并导出静态库包 <a class="header-anchor" href="#part-2-export" aria-label="Permalink to &quot;CMake怎样安装并导出静态库包 {#part-2-export}&quot;">​</a></h3><p>install(TARGETS ... EXPORT P2ReportTargets) 收集真实目标；install(EXPORT ...) 生成带 P2:: 命名空间的目标描述；公共头和静态归档必须同时安装。只有 Targets 文件还不等于 find_package 可发现的包，入口 Config 负责 include 它并检查组件。</p><p>configure_package_config_file 生成 P2ReportConfig.cmake，write_basic_package_version_file 生成版本兼容判断。项目1.0.0声明 SameMajorVersion，消费者请求1可接受同主版本且满足请求的版本；这只是包声明的兼容政策，不会分析 C++ ABI 是否真的兼容。作者仍需维护 API/ABI 或调整版本策略。</p><p>p2_options 被库的导出用法要求引用，必须一起进入 export 集。本例导出 options/report，CLI 安装到 bin 但不导出为库接口。静态库无需共享库导出宏；若改成 SHARED，还须重新处理 Windows 符号可见性、运行库搜索与 ABI，不能只改一个关键字就声称跨平台完成。</p><h3 id="part-2-find" tabindex="-1">下游工程怎样用find_package消费安装包 <a class="header-anchor" href="#part-2-find" aria-label="Permalink to &quot;下游工程怎样用find_package消费安装包 {#part-2-find}&quot;">​</a></h3><p>独立 consumer 用 find_package(P2Report 1 CONFIG REQUIRED)，再 PRIVATE 链接 P2::report。CMAKE_PREFIX_PATH 指向安装前缀，CMake 在常规子目录寻找 Config；P2Report_DIR 则直接指向 Config 所在目录，两者不能混成 include 路径。</p><p>消费者不使用上游源码树。检验可搬移性时把已安装的完整前缀复制到另一位置，另建空的 consumer 构建目录，让 <code>CMAKE_PREFIX_PATH</code> 指向新前缀。Linux x86_64 的本次验证对两个前缀均得到 <code>consumer bytes=4 newlines=1</code>。<a href="https://cmake.org/cmake/help/v3.28/manual/cmake-packages.7.html#creating-relocatable-packages" target="_blank" rel="noopener noreferrer">CMake 的可搬移包说明</a></p><p>多个版本同时存在时，旧 P2Report_DIR 缓存可能让查找继续命中旧包。先看配置日志和缓存的实际 Config 位置；不要用手写 -I/-L 来“修复”目标传播。版本文件可拒绝不兼容版本，但无法把不同架构静态库转换成可用产物。</p><h3 id="part-2-exercise" tabindex="-1">练习与自检 <a class="header-anchor" href="#part-2-exercise" aria-label="Permalink to &quot;练习与自检 {#part-2-exercise}&quot;">​</a></h3><p>假设公共 report.hpp 改为 include 一个外部库头。说明 PUBLIC/PRIVATE 与 Config 应怎样调整。</p><details><summary>参考答案与判断依据</summary><p>外部库的 imported target 应成为 report 的 PUBLIC 依赖，因为消费者需要它的头和用法要求。安装 Config 需要 include(CMakeFindDependencyMacro) 并 find_dependency 对应包，然后才 include 自己的 Targets。不能把开发机外部 include 绝对路径写进安装接口。</p></details><h3 id="part-2-sources" tabindex="-1">一手资料与验证边界 <a class="header-anchor" href="#part-2-sources" aria-label="Permalink to &quot;一手资料与验证边界 {#part-2-sources}&quot;">​</a></h3><p>2026-10-17核对 <a href="https://cmake.org/cmake/help/v3.28/manual/cmake-presets.7.html" target="_blank" rel="noopener noreferrer">CMake 3.28 Presets</a>、<a href="https://cmake.org/cmake/help/v3.28/guide/importing-exporting/index.html" target="_blank" rel="noopener noreferrer">导入导出指南</a>、<a href="https://cmake.org/cmake/help/v3.28/module/CMakePackageConfigHelpers.html" target="_blank" rel="noopener noreferrer">PackageConfigHelpers</a>。复现步骤与独立消费者的输出见<a href="/programming/cpp/plus/practice/build-application#acceptance">安装后消费</a>。</p>',47)])])}const h=a(i,[["render",n]]);export{u as __pageData,h as default};
